    list.add(new Guides.Entry("Afet kurumları ve süreç","Hastane ve sağlık erişimi","Acil durumda 112 üzerinden sevk yönlendirmesi al. Hastane kapasitesi afet sırasında değişebilir. Kendi araçla tehlikeli güzergâha giriş yerine yetkililerin yönlendirmesini izle."));
    list.add(new Guides.Entry("Afet kurumları ve süreç","Gönüllülükte koordinasyon","Eğitim ve görev çağrısı olmadan riskli alanda kurtarma yapma. İhtiyaçların ve lojistiğin yetkili kurumlarca koordine edilmesi önemlidir. Kendi güvenliğini ve trafik akışını engelleme."));
